import db from "App/db/db";

// Live annotations generated by the given system source annotations
// (`systemSourceAnnotationId`). `projectId` narrows the scan to one project
// (indexed); without it the whole table is filtered.
export default async function collectSystemChildren({ sourceIds, projectId }) {
  const set = new Set((sourceIds ?? []).filter(Boolean));
  if (set.size === 0) return [];
  const collection = projectId
    ? db.annotations.where("projectId").equals(projectId)
    : db.annotations.toCollection();
  return collection
    .filter((a) => !a.deletedAt && set.has(a.systemSourceAnnotationId))
    .toArray();
}
